import {performance} from 'node:perf_hooks';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {materializeRuntimeRoot,runtimeRootDescriptor,validateRuntimeRootDescriptor} from './runtime-root-verified.mjs';

const WORKSPACE=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const ORIENTATION=['README.md','BOOTSTRAP.json','ADMISSION.json','AGENTS.md','TERMS.md'];
const REMOTE=['src/runtime-root-verified.mjs','runtime-root/shard-000.json','runtime-root/shard-001.json','runtime-root/shard-002.json','runtime-root/shard-003.json','runtime-root/shard-004.json','runtime-root/shard-005.json','runtime-root/shard-006.json'];
const HEX40=/^[a-f0-9]{40}$/;const HEX64=/^[a-f0-9]{64}$/;
const sha256=b=>crypto.createHash('sha256').update(Buffer.isBuffer(b)?b:Buffer.from(String(b))).digest('hex');
function gitBlobSha1(bytes){const b=Buffer.isBuffer(bytes)?bytes:Buffer.from(bytes);return crypto.createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex');}
function digestObject(value,key='receipt_sha256'){const x=structuredClone(value||{});delete x[key];return sha256(Buffer.from(JSON.stringify(x)));}
function atomicJson(file,value){fs.mkdirSync(path.dirname(file),{recursive:true});const tmp=file+'.tmp-'+crypto.randomUUID();const fd=fs.openSync(tmp,'wx',0o600);try{fs.writeFileSync(fd,JSON.stringify(value,null,2)+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.renameSync(tmp,file);return JSON.parse(fs.readFileSync(file,'utf8'));}
function exactCopy(src,dst){const b=fs.readFileSync(src);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.writeFileSync(dst,b,{mode:0o600});if(!fs.readFileSync(dst).equals(b))throw new Error('deployment copy readback mismatch:'+src);return b;}
function gitHead(workspace){const x=execFileSync('git',['rev-parse','HEAD'],{cwd:workspace,encoding:'utf8'}).trim().toLowerCase();if(!HEX40.test(x))throw new Error('deployment git HEAD unavailable');return x;}
function expectedTransportObjects(store,d){return [{path:d.loader.path,blob_sha1:d.loader.blob_sha1},...d.shards.map(s=>({path:s.path,blob_sha1:s.blob_sha1}))].map(x=>{const b=fs.readFileSync(path.join(store,x.path));if(gitBlobSha1(b)!==x.blob_sha1)throw new Error('deployment transport object identity mismatch:'+x.path);return{...x,sha256:sha256(b),bytes:b.length};});}
function verifyMaterializedRoot(root,d){for(const m of d.members){const b=fs.readFileSync(path.join(root,m.path));if(b.length!==m.bytes||gitBlobSha1(b)!==m.blob_sha1)throw new Error('deployed runtime member readback mismatch:'+m.path);}return true;}
function termsInfo(store){const bytes=fs.readFileSync(path.join(store,'TERMS.md'));return{text:bytes.toString('utf8'),digest:sha256(bytes)};}
function orientationDigests(store){return Object.fromEntries(ORIENTATION.map(p=>[p,sha256(fs.readFileSync(path.join(store,p))) ]));}
function sessionKey(id){const s=String(id||'').trim();if(!s)throw new Error('session id required');return sha256(Buffer.from(s)).slice(0,32);}
function signReceipt(material){return{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material))) };}
function signTicket(material){return{...material,ticket_sha256:sha256(Buffer.from(JSON.stringify(material))) };}
function readLastState(runtimeDir){const f=path.join(runtimeDir,'.ikant','ledger.jsonl');if(!fs.existsSync(f))return null;const rows=fs.readFileSync(f,'utf8').trim().split('\n').filter(Boolean).map(JSON.parse);return rows.at(-1)?.state_after||null;}

export function deploySessionChatRuntime({workspace=WORKSPACE,deploymentRoot,sourceHead=null,deploymentId=null}={}){
 const root=path.resolve(String(deploymentRoot||''));if(!deploymentRoot)throw new Error('deploymentRoot required');if(fs.existsSync(root))throw new Error('deployment root exists');
 const observedHead=gitHead(workspace),pin=String(sourceHead||observedHead).toLowerCase();if(pin!==observedHead||!HEX40.test(pin))throw new Error('deployment source pin mismatch');
 const sourceDescriptor=runtimeRootDescriptor(workspace),dv=validateRuntimeRootDescriptor(sourceDescriptor);if(!dv.ok)throw new Error('deployment runtime descriptor invalid:'+dv.errors.join(','));
 const store=path.join(root,'store');fs.mkdirSync(store,{recursive:true});for(const rel of [...ORIENTATION,...REMOTE])exactCopy(path.join(workspace,rel),path.join(store,rel));
 const d=runtimeRootDescriptor(store),v=validateRuntimeRootDescriptor(d);if(!v.ok||d.runtime_root_sha256!==sourceDescriptor.runtime_root_sha256)throw new Error('deployment store descriptor drift');
 const objects=expectedTransportObjects(store,d);
 const transfer=signReceipt({schema:'ikant-le-deployment-store-transfer/v1',source_head:pin,runtime_root_sha256:d.runtime_root_sha256,objects,complete:true,bytes_exact:true,model_mediated_bytes:false,authority:0});
 atomicJson(path.join(root,'deployment-transfer.json'),transfer);
 const referenceRoot=path.join(root,'reference-runtime');const mat=materializeRuntimeRoot({workspace:store,sink:referenceRoot,sourceHead:pin,reusePaths:ORIENTATION,transferReceiptSha256:transfer.receipt_sha256});verifyMaterializedRoot(referenceRoot,d);
 const material={schema:'ikant-le-session-chat-deployment/v1',deployment_id:String(deploymentId||crypto.randomUUID()),source_head:pin,runtime_root_sha256:d.runtime_root_sha256,transport_object_count:objects.length,transport_objects:objects,deployment_transfer_receipt_sha256:transfer.receipt_sha256,reference_materialization_receipt_sha256:mat.receipt_sha256,reference_root_reopen_verified:true,repository_transfer_per_chat:false,session_model:'ATTEST_AND_BIND_EXISTING_RUNTIME',acceptance_ingress:'MONOTONIC_RUNTIME_INGEST',runtime_execution_plane:'DEPLOYMENT_LOCAL_NODE',physical_chatgpt_registration_proven:false,authority:0};
 const attestation=signReceipt(material);atomicJson(path.join(root,'deployment.json'),attestation);return attestation;
}

export function readSessionChatDeployment(deploymentRoot){
 const root=path.resolve(String(deploymentRoot||'')),file=path.join(root,'deployment.json');const dep=JSON.parse(fs.readFileSync(file,'utf8'));if(dep.schema!=='ikant-le-session-chat-deployment/v1'||dep.authority!==0||digestObject(dep)!==dep.receipt_sha256)throw new Error('deployment attestation invalid');if(!HEX40.test(String(dep.source_head||''))||!HEX64.test(String(dep.runtime_root_sha256||'')))throw new Error('deployment identity invalid');
 const transfer=JSON.parse(fs.readFileSync(path.join(root,'deployment-transfer.json'),'utf8'));if(transfer.schema!=='ikant-le-deployment-store-transfer/v1'||transfer.authority!==0||digestObject(transfer)!==transfer.receipt_sha256||transfer.receipt_sha256!==dep.deployment_transfer_receipt_sha256||transfer.source_head!==dep.source_head||transfer.runtime_root_sha256!==dep.runtime_root_sha256)throw new Error('deployment transfer invalid');
 const store=path.join(root,'store'),d=runtimeRootDescriptor(store),v=validateRuntimeRootDescriptor(d);if(!v.ok||d.runtime_root_sha256!==dep.runtime_root_sha256)throw new Error('deployment store invalid');const objects=expectedTransportObjects(store,d);if(objects.length!==dep.transport_object_count||JSON.stringify(objects)!==JSON.stringify(dep.transport_objects))throw new Error('deployment object drift');verifyMaterializedRoot(path.join(root,'reference-runtime'),d);return{root,store,descriptor:d,objects,deployment:dep};
}

export function openDeployedSession({deploymentRoot,sessionId}={}){const dep=readSessionChatDeployment(deploymentRoot),terms=termsInfo(dep.store),base=path.join(dep.root,'sessions',sessionKey(sessionId)),state=readLastState(path.join(base,'runtime')),active=state?.status==='ACTIVE';return{schema:'ikant-le-deployed-session-open/v1',deployment_id:dep.deployment.deployment_id,source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,terms_text:terms.text,terms_digest:terms.digest,acceptance_required:!active,active,repository_transfer_per_chat:false,authority:0};}

function buildPreacceptHandoff(dep,pendingIntent){const terms=termsInfo(dep.store),pending=String(pendingIntent??'inizializza iKant_LE');return{schema:'ikant-le-preaccept-handoff/v1',repository:'Luke883i/iKant_LE',source_head:dep.deployment.source_head,terms_presented:true,terms_digest:terms.digest,frozen:true,breached:false,pending_intent:pending,pending_intent_sha256:sha256(Buffer.from(pending)),orientation_digests:orientationDigests(dep.store),runtime_observed_terms_presentation:false,host_attested_terms_presentation:true,authority:0};}
function buildWarmTransfer(dep,elapsed){return signReceipt({schema:'ikant-le-source-bound-transfer/v2',source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,mode:'WARM_CACHE_EXACT',transport_authority:0,identity_authority:'CONTENT_ADDRESSING',exact_ref:true,bridge_observed:true,model_mediated_bytes:false,complete:true,bytes_exact:true,remote_objects:dep.objects,remote_rounds:0,remote_reads:0,locator_pinned:false,archive_policy:null,host_readback_verified:false,cache_reopen_verified:true,elapsed_ms:elapsed,authority:0});}
function buildConvergence(dep,eventId,transfer,runtimeDir){const a=signReceipt({schema:'ikant-le-fastboot-carrier-attempt/v1',attempt_id:'deployed-'+eventId,carrier:'WARM_CACHE_EXACT',acceptance_event_id:eventId,source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,result:'COMPLETE',source_object_identity:'deployment:'+dep.deployment.deployment_id+':'+dep.descriptor.runtime_root_sha256,runtime_sink_object_id:'runtime:'+sha256(Buffer.from(runtimeDir)),remote_objects:dep.objects,remote_reads:0,bytes_observed:dep.objects.reduce((n,x)=>n+x.bytes,0),source_fetch_observed:true,byte_preserving_runtime_sink_observed:true,runtime_materializer_bound:true,runtime_executor_bound:true,model_mediated_bytes:false,authoritative_remote_history:false,committed_remote_rounds:0,transfer_receipt_sha256:transfer.receipt_sha256,authority:0});return signReceipt({schema:'ikant-le-fastboot-convergence/v1',acceptance_event_id:eventId,source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,attempts:[a],selected_carrier:'WARM_CACHE_EXACT',committed_transfer_receipt_sha256:transfer.receipt_sha256,remote_history_commits:1,materially_distinct_retry:false,acceptance_preserved:true,source_preserved:true,deadline_origin_preserved:true,model_mediated_bytes:false,authority:0});}
function buildOriginReceipt(ticket,runtimeEntry){const elapsed=Math.max(0,Number(runtimeEntry)-Number(ticket.origin_monotonic_ms));const material={schema:'ikant-le-acceptance-origin/v2',event_id:ticket.event_id,source_head:ticket.source_head,terms_digest:ticket.terms_digest,deadline_origin:'I_ACCEPT',clock:'MONOTONIC',observed_at_accept:true,origin_ticket:ticket,origin_monotonic_ms:ticket.origin_monotonic_ms,runtime_entry_monotonic_ms:Number(runtimeEntry),elapsed_to_runtime_entry_ms:elapsed,authority:0};return signReceipt(material);}

export async function acceptDeployedSession({deploymentRoot,sessionId,humanInput,pendingIntent='inizializza iKant_LE',monotonicNow=()=>performance.now(),probeRunner=null}={}){
 const origin=Number(monotonicNow());if(String(humanInput)!=='I ACCEPT'){const e=new Error('exact I ACCEPT required');e.code='IKANT_ACCEPT_EXACT_REQUIRED';throw e;}
 const dep=readSessionChatDeployment(deploymentRoot),terms=termsInfo(dep.store),base=path.join(dep.root,'sessions',sessionKey(sessionId));if(fs.existsSync(path.join(base,'acceptance-origin-ticket.json'))||fs.existsSync(path.join(base,'runtime','.ikant','ledger.jsonl')))throw new Error('session acceptance already consumed');fs.mkdirSync(base,{recursive:true});
 const eventId='acceptance-event-'+crypto.randomUUID();const ticket=signTicket({schema:'ikant-le-acceptance-origin-ticket/v1',event_id:eventId,source_head:dep.deployment.source_head,terms_digest:terms.digest,deadline_origin:'I_ACCEPT',clock:'MONOTONIC',observed_at_accept:true,origin_monotonic_ms:origin,authority:0});atomicJson(path.join(base,'acceptance-origin-ticket.json'),ticket);
 const transfer=buildWarmTransfer(dep,Math.max(0,Number(monotonicNow())-origin)),runtimeDir=path.join(base,'runtime'),convergence=buildConvergence(dep,eventId,transfer,runtimeDir);const mat=materializeRuntimeRoot({workspace:dep.store,sink:runtimeDir,sourceHead:dep.deployment.source_head,reusePaths:ORIENTATION,transferReceiptSha256:transfer.receipt_sha256});
 const runtimeEntry=Number(monotonicNow()),originReceipt=buildOriginReceipt(ticket,runtimeEntry);atomicJson(path.join(runtimeDir,'.ikant','acceptance-origin.json'),originReceipt);
 const handoff=buildPreacceptHandoff(dep,pendingIntent);const evidenceMaterial={schema:'ikant-le-chat-bootstrap-evidence/v1',source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,acceptance_event_id:eventId,acceptance_origin_receipt_sha256:originReceipt.receipt_sha256,acceptance_origin:originReceipt,transfer_receipt_sha256:transfer.receipt_sha256,materialization_receipt_sha256:mat.receipt_sha256,fastboot_convergence:convergence,transfer,authority:0};const evidence=signReceipt(evidenceMaterial);
 const mod=await import(pathToFileURL(path.join(runtimeDir,'src/runtime.mjs')).href+'?session='+encodeURIComponent(eventId));let first=true;const runClock=()=>{if(first){first=false;return runtimeEntry;}return Number(monotonicNow());};const options={preacceptHandoff:handoff,postAcceptBootstrapEvidence:evidence,hostEngine:'IKANT_LE_DEPLOYED_SESSION',hostSurface:'SESSION_CHAT_DEPLOYED_RUNTIME',monotonicNow:runClock};if(probeRunner)options.probeRunner=probeRunner;const out=mod.runCommand('I ACCEPT',options);
 const state=readLastState(runtimeDir);if(out.code!==0||state?.status!=='ACTIVE')throw new Error('deployed session failed to reach ACTIVE');
 return{schema:'ikant-le-deployed-session-active/v1',state:'ACTIVE',deployment_id:dep.deployment.deployment_id,source_head:dep.deployment.source_head,runtime_root_sha256:dep.descriptor.runtime_root_sha256,session_key:sessionKey(sessionId),acceptance_event_id:eventId,acceptance_origin_ticket_sha256:ticket.ticket_sha256,acceptance_origin_receipt_sha256:originReceipt.receipt_sha256,transfer_receipt_sha256:transfer.receipt_sha256,materialization_receipt_sha256:mat.receipt_sha256,bootstrap_receipt_sha256:state.bootstrap?.last_receipt_sha256||null,deadline_result:state.bootstrap?.deadline_result||null,deadline_elapsed_ms:state.bootstrap?.deadline_elapsed_ms??null,transfer_mode:'WARM_CACHE_EXACT',remote_rounds:0,repository_transfer_per_chat:false,runtime_readback_active:true,stdout:out.stdout,authority:0};
}

export async function runDeployedSessionTurn({deploymentRoot,sessionId,input}={}){
 const dep=readSessionChatDeployment(deploymentRoot),base=path.join(dep.root,'sessions',sessionKey(sessionId)),runtimeDir=path.join(base,'runtime'),before=readLastState(runtimeDir);if(before?.status!=='ACTIVE')throw new Error('deployed session not ACTIVE');
 const mod=await import(pathToFileURL(path.join(runtimeDir,'src/runtime.mjs')).href+'?turn='+encodeURIComponent(crypto.randomUUID()));const out=mod.runCommand(String(input??''),{hostEngine:'IKANT_LE_DEPLOYED_SESSION',hostSurface:'SESSION_CHAT_DEPLOYED_RUNTIME'}),after=readLastState(runtimeDir);
 return{schema:'ikant-le-deployed-session-turn/v1',code:out.code,stdout:out.stdout,state:after?.status||null,runtime_readback:true,authority:0};
}
